document.addEventListener('change',e=>{if(store.isCloud()&&/^filter/.test(e.target.id)){cloudPage=0;cloudCursors=[null];}if(e.target.id==='cloudSearchField'){cloudSearchField=e.target.value;filter.q='';cloudSearchTerm='';cloudPage=0;cloudCursors=[null];render();}if(e.target.id==='auditFilter'){auditFilter=e.target.value;auditPage=0;render();}if(e.target.id==='requestType'){const form=e.target.form,st=form._rolLookup;clearPriorRolLookup(form);const kept=Object.fromEntries(schema(st.type).map(f=>[f.id,lookupField(form,f.id)?.value||'']));form.querySelector('#requestSpecificFields').innerHTML=requestSpecificFields(e.target.value,kept);st.type=e.target.value;runRolLookup(form);}if(e.target.name==='rol'&&e.target.form?._rolLookup)runRolLookup(e.target.form);if(e.target.id==='historyKind'){historyKind=e.target.value;historyPage=0;render();}if(e.target.id==='propertyKind'){propertyKind=e.target.value;render();}if(e.target.id==='pilotRole'){store.settings.role=e.target.value;notifications=[];store.refreshNotifications();render(true);}if(e.target.id==='filterStage'){filter.stage=e.target.value;render();}if(e.target.id==='filterPayment'){filter.payment=e.target.value;render();}if(e.target.id==='filterResponsible'){filter.responsible=e.target.value;render();}if(e.target.id==='filterType'){filter.type=e.target.value;render();}if(e.target.id==='filterChannel'){filter.channel=e.target.value;render();}});
