function onRecords(list){if(store.isCloud()&&list.some(r=>r.id===route().split('/')[1]))cloudDetailLoading=false;records=dataAudit?list.map(r=>({...r,dataQuality:qualityForRol(dataAudit,r.rol)})):list;render();if(!dataAudit&&!auditLoading)ensureDataAudit();}function onStoreError(e){toast(e.message,true);}
const management=createManagement({actor:store.actor,isCloud:store.isCloud,records:()=>records,certificateStages:STAGES,today,render:()=>render(),toast,download:store.download,directory:()=>[...team,...Object.entries(CASE_ROLES).filter(([role])=>!['administrativo','profesional','director'].includes(role)).map(([role,label])=>({id:'pilot-'+role,name:'Prueba · '+label,roles:[role],enabled:true}))]});
try{await refreshSync();await store.init();store.subscribe(onRecords,onStoreError);if(!store.isCloud()||store.currentUser())subscribeTeam();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});}catch(e){app.innerHTML=`<main class="login"><div class="login-card"><h1>No se pudo conectar</h1><p class="error">${h(e.message)}</p><p>Revisa la configuración del proyecto Firebase o vuelve al piloto local.</p>${btn('Usar piloto local','resetConfig')}</div></main>`;app.querySelector('[data-action="resetConfig"]')?.addEventListener('click',()=>store.localMode());}

function draftPanel(r){const folder=DRAFT_FOLDERS[r.type],current=r.archive?.current&&r.archive.documentVersion===r.documentVersion;return panel('Documento para firma externa',`<div class="panel-body"><div class="draft-status"><span class="badge amber">${['SIGNED','DELIVERED'].includes(r.stage)?'Firma incorporada':'Firma externa pendiente'}</span><span class="badge ${current?'green':'gray'}">${current?'Guardado en carpeta':'Pendiente de archivo en carpeta'}</span></div><p>Formato ${MUNICIPAL_TEMPLATES[r.type]?'municipal de '+TYPES[r.type]:r.type==='AUP'?'Formulario MINVU 5.4':r.type==='CIP'?'Formulario MINVU 5.2':r.type==='CNU'?'Formulario MINVU 5.5':'institucional de Permiso y Recepción'}. PDF con texto editable${(r.type==='CPYR'||MUNICIPAL_TEMPLATES[r.type])?' y archivo Word editable':''}. Los cambios posteriores a la validación requieren nueva revisión.</p><div class="button-row">${btn('Descargar PDF editable','editablePdf','btn-primary')}${(r.type==='CPYR'||MUNICIPAL_TEMPLATES[r.type])?btn('Descargar Word','editableWord'):''}${r.number&&['READY','APPROVED'].includes(r.stage)&&may(r,'archive')?btn(current?'Volver a guardar en carpeta':'Guardar en Borradores','archiveDraft'):''}<a class="btn" href="#demo" target="_blank" rel="noopener noreferrer">${'Abrir carpeta '+r.type+' en Drive'}</a></div>${current?`<div class="archive-receipt"><b>${h(r.archive.folder)}</b><p>Versión ${r.archive.documentVersion} · ${date(r.archive.at)} · Escritura local verificada; sincronización con Drive no comprobada.</p>${r.archive.files.map(f=>`<small>${h(f.name)} · ${f.size.toLocaleString('es-CL')} bytes<br>SHA-256: ${f.sha256}</small>`).join('<br>')}</div>`:'<p class="subtitle">La descarga de prueba se realiza en este dispositivo. No se envían archivos a Drive.</p>'}</div>`);}
let documentBlocks=[];
function documentEditor(r){const scene=certificateScene(r);documentBlocks=scene.pages.flatMap(p=>p.ops).filter(o=>o.kind==='text'&&!o.system);dialog('Editar texto completo del certificado',`<p class="subtitle">Edita títulos, redacción, etiquetas y valores de cada página. Esta edición modifica el documento; para actualizar también la ficha de datos, utiliza Editar datos y antecedentes. Los datos de número, fecha del certificado, pago y la indicación de firma pendiente se gestionan en el flujo. Para textos extensos utiliza Observaciones técnicas en Editar datos y antecedentes.</p><p class="warning">Cualquier cambio conserva la versión anterior y devuelve el certificado a preparación. Si luego cambias los datos estructurados, se descartan las sustituciones cuyo texto de origen cambió.</p>${scene.pages.map((p,i)=>`<details class="field-group" ${i===0?'open':''}><summary>Página ${i+1} · ${p.ops.filter(o=>o.kind==='text'&&!o.system).length} bloques editables</summary><div class="form-grid">${p.ops.filter(o=>o.kind==='text'&&!o.system).map(o=>`<div class="field"><label for="doc_${o.id}">${h(o.original.slice(0,65)||'Campo vacío')} <small>Texto ${p.ops.filter(v=>v.kind==='text'&&!v.system).indexOf(o)+1}</small></label>${o.blockText?`<textarea id="doc_${o.id}" data-document-id="${o.id}" maxlength="1000" rows="4">${h(o.text)}</textarea>`:`<input id="doc_${o.id}" data-document-id="${o.id}" value="${h(o.text)}" maxlength="300">`}</div>`).join('')}</div></details>`).join('')}${input('reason','Motivo de la edición documental','','textarea',true)}`,'documentForm','Guardar nueva versión',true);}

function managesAccounts(){return store.actor().enabled!==false&&(store.actor().baseRoles||store.actor().roles).includes('director');}
async function loadAccess(){if(!managesAccounts()||accessLoading)return;accessLoading=true;try{accessData=await store.listAccess();accessError='';}catch(e){accessError=e.message;}finally{accessLoading=false;render();}}
function teamView(){const manage=managesAccounts(),cloud=store.isCloud();if(manage&&!accessData&&!accessLoading&&!accessError)loadAccess();const users=manage?(accessData?.users||[]):team;return heading('Equipo y cuentas','Acceso con Google, identidad permanente y responsabilidades por funcionario.',manage?btn('Agregar usuario','accessInvite','btn-primary'):'')+panel('Identidad y permisos',`<div class="panel-body"><p>Cada funcionario utiliza su cuenta Google. El primer acceso queda pendiente hasta la habilitación del director. El UID identifica permanentemente a la persona; no se comparten cuentas ni se elige una función al ingresar.</p><p>La baja bloquea nuevas operaciones y solicita la revocación de sesiones. Las subrogancias tienen fecha de inicio, término y acto de respaldo. El subrogante puede gestionar el flujo durante ese período; la administración de cuentas corresponde al director titular.</p>${!cloud?'<div class="warning">Demostración local: las cuentas agregadas son simuladas. Firebase y la nómina municipal deben habilitarse para operar entre equipos.</div>':''}</div>`)+panel(manage?'Nómina y solicitudes de acceso':'Cuentas habilitadas',`<div class="panel-body">${accessError?`<p class="error">${h(accessError)}</p>`:''}${manage?btn('Actualizar nómina','accessRefresh'):''}${accessLoading?'<p>Cargando cuentas…</p>':''}</div><div class="table-wrap"><table><thead><tr><th>Funcionario / UID permanente</th><th>Correo Google</th><th>Funciones</th><th>Estado / subrogancia</th><th>Administración</th></tr></thead><tbody>${users.map(u=>`<tr><td><b>${h(u.name)}</b><small class="muted tiny">${h(u.id)}</small></td><td>${h(u.email)}</td><td>${(u.roles||[]).map(r=>h(ROLES[r]||r)).join(' · ')||'Pendiente de asignar'}</td><td>${h(({PENDING:'Pendiente de validación',DISABLED:'De baja',ACTIVE:'Habilitado'})[u.status]||(u.enabled?'Habilitado':'De baja'))}${u.delegation?`<small class="muted tiny">Subrogancia: ${date(new Date(u.delegation.startMs).toISOString())} a ${date(new Date(u.delegation.endMs).toISOString())}<br>${h(u.delegation.reference)}</small>`:''}${u.revocationStatus==='PENDING'?'<small class="muted tiny">Revocación de sesiones en proceso</small>':''}</td><td>${manage&&u.id!==store.actor().id?`<div class="row-actions">${(u.status==='PENDING'?[['approve','Validar y habilitar']]:u.enabled?[['permissions','Cambiar permisos'],['disable','Dar de baja'],...(u.roles.includes('profesional')&&!u.roles.includes('director')?[['delegate','Subrogancia']]:[]),...(u.delegation?[['endDelegation','Finalizar subrogancia']]:[])]:[['reactivate','Reactivar']]).map(([mode,label])=>btn(label,'accessUser',mode==='disable'?'btn-sm btn-danger':'btn-sm',`data-uid="${h(u.id)}" data-mode="${mode}"`)).join('')}</div>`:'—'}</td></tr>`).join('')}</tbody></table></div>`)+(manage?panel('Incorporaciones por correo',`<div class="panel-body"><p>Agregar un correo a la nómina no habilita el acceso. La persona debe ingresar con Google y luego el director valida su UID.</p>${(accessData?.invites||[]).map(i=>`<p><b>${h(i.name)}</b> · ${h(i.email)} · ${i.claimedUid?'Cuenta Google presentada; revisar nómina':'Esperando primer acceso con Google'}</p>`).join('')||'<p>Sin incorporaciones pendientes.</p>'}</div>`)+panel('Bitácora de accesos',`<div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Acción / cuenta</th><th>Responsable y motivo</th></tr></thead><tbody>${(accessData?.events||[]).map(e=>`<tr><td>${date(e.at)}</td><td>${h(({invite:'Alta en nómina',REQUEST_ACCESS:'Solicitud de acceso',approve:'Habilitación',permissions:'Cambio de permisos',disable:'Baja',reactivate:'Reactivación',delegate:'Subrogancia',endDelegation:'Fin de subrogancia'})[e.action]||e.action)}<small class="muted tiny">${h(e.email||e.after?.email||'')} · ${h(e.uid||'UID pendiente')}</small></td><td>${h(e.actorEmail||e.actorId)}<small class="muted tiny">${h(e.reason||'Primer acceso con Google')}</small></td></tr>`).join('')}</tbody></table></div>`):'');}
function accessDialog(uid,mode){if(!managesAccounts())throw Error('Solo el director titular administra las cuentas.');const u=accessData?.users.find(u=>u.id===uid),labels={invite:'Agregar usuario Google',approve:'Validar y habilitar cuenta',permissions:'Cambiar permisos',disable:'Dar de baja',reactivate:'Reactivar cuenta',delegate:'Registrar subrogancia',endDelegation:'Finalizar subrogancia'};let body=u?`<p><b>${h(u.name)}</b> · ${h(u.email)}</p><p class="subtitle">UID permanente: ${h(u.id)}</p>`:'';
 if(mode==='invite')body+=input('name','Nombre del funcionario','','text',true)+input('email','Correo Google','','email',true)+`<div class="field"><label>Función propuesta</label><select name="role"><option value="profesional">Profesional</option><option value="administrativo">Administrativo</option><option value="director">Director titular</option></select></div><p>Debe ingresar con Google y ser validado después. Esta acción registra la incorporación; no envía correos.</p>`;
 if(['approve','permissions','reactivate'].includes(mode))body+=`<p>Funciones autorizadas:</p>${['administrativo','profesional','director'].map(role=>`<label class="checks checkbox-block"><input type="checkbox" name="roles" value="${role}" ${(u.roles?.length?u.roles:u.requestedRoles||[]).includes(role)?'checked':''}>${ROLES[role]}</label>`).join('')}<p>La aprobación final siempre requiere una persona distinta de quien preparó el certificado.</p>`;
 if(mode==='delegate')body+=input('start','Inicio de subrogancia','','datetime-local',true)+input('end','Término de subrogancia','','datetime-local',true)+input('reference','Acto o referencia de autorización','','text',true);
 if(mode==='disable')body+='<div class="warning">Se bloquean las operaciones y se revocan las sesiones. El historial, los documentos y las asignaciones se conservan; revisa y reasigna los trámites pendientes.</div>';
 body+=input('reason','Motivo y respaldo del cambio','','textarea',true);dialog(labels[mode],body,'accessForm','Registrar cambio',true,null);modal.dataset.accessAction=mode;modal.dataset.accessUid=uid||'';modal.dataset.accessRevision=String(u?.accessRevision||0);
}


function entryDialog(r){dialog('Editar ingreso',`<p class="subtitle">Corrige los datos de registro. La versión anterior se conserva y el borrador vuelve a preparación. Si cambias el tipo, se conservan los campos comunes y se limpian los antecedentes específicos del certificado anterior.</p><div class="form-grid"><div class="field"><label for="entryType">Tipo de certificado *</label><select id="entryType" name="type">${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${r.type===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="entryChannel">Canal *</label><select id="entryChannel" name="channel"><option value="PRESENCIAL" ${r.channel==='PRESENCIAL'?'selected':''}>Presencial</option><option value="DOMEL" ${r.channel==='DOMEL'?'selected':''}>DOM en Línea</option></select></div>${input('applicant','Solicitante',r.applicant,'text',true)}${input('applicantRut','RUT del solicitante',r.applicantRut)}${input('rol','ROL',r.rol,'text',true)}${input('email','Correo de contacto',r.email,'email')}${input('receivedDate','Fecha de ingreso',r.receivedDate,'date',true)}${input('entry','Ingreso municipal',r.entry)}${input('folio','Folio DOMEL',r.folio)}</div>${input('reason','Motivo de la corrección','','textarea',true)}`,'editEntryForm','Guardar corrección',true,r);}

function deletedDetail(r){return heading('Ingreso en papelera',`${h(r.type)} · ROL ${h(r.rol)} · ${h(r.applicant)}`,`<a class="btn" href="#requests">Volver al control de certificados</a>`)+panel('Eliminación recuperable',`<div class="panel-body"><p>${r.purgeLock?'La eliminación definitiva está iniciada. Vuelve a Papelera y usa Vaciar papelera para completar la limpieza; este ingreso ya no puede recuperarse.':'Este ingreso se retiró del trabajo activo. Sus datos y antecedentes se conservan.'}</p>${fact('Fecha de eliminación',date(r.deletedAt))}<br>${fact('Motivo',r.deletionReason)}<div class="button-row">${may(r,'restoreEntry')?btn('Recuperar ingreso','restoreEntry','btn-primary'):''}</div></div>`)+panel('Historial conservado',`<div class="panel-body"><ul class="activity-list">${[...r.history].reverse().map(e=>`<li>${h(e.action)}<small>${h(e.actor)}${e.actorEmail?' · '+h(e.actorEmail):''} · ${date(e.at)}</small></li>`).join('')}</ul><p>${r.attachments.length} archivo(s) conservados. Recupera el ingreso para gestionarlos desde su ficha.</p></div>`);}

document.addEventListener('click',e=>{const row=e.target.closest('tr[data-form-route]');if(row&&!e.target.closest('a,button,input,select,textarea'))location.hash=row.dataset.formRoute;});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('tr[data-form-route]'))location.hash=e.target.dataset.formRoute;});


function dataQualityPanel(r){const q=r.dataQuality;if(!q?.requiresAddressReview)return '';return panel('Identificación del predio: revisión requerida',`<div class="panel-body"><div class="warning"><b>ROL ${h(r.rol)}: existen direcciones discordantes.</b><p>Se prioriza la dirección documental cuando es única. El catastro se conserva como referencia. Revisa también que el contorno corresponda al predio antes de utilizar su zona o sus cotas.</p></div>${r.fields.street?`<p><b>Dirección de esta versión:</b> ${h([r.fields.street,r.fields.houseNumber].filter(Boolean).join(' '))}</p>`:''}<ul>${q.candidates.map(c=>`<li><b>${h(c.label)}:</b> ${h(c.raw)}</li>`).join('')}</ul><p>${h((q.documentaryReferences||[]).join(' · '))}</p>${r.qualityReview?`<p><b>Revisión registrada:</b> ${h(r.qualityReview.reason)} · ${h(r.qualityReview.actorEmail||r.qualityReview.actorId)}</p>`:'<p>Antes del envío a dirección, el profesional debe registrar el antecedente cotejado y confirmar la identificación.</p>'}<a class="btn-link" href="#audit">Ver auditoría de todas las fuentes</a></div>`);}
async function ensureDataAudit(withRows=false){if(auditLoading)return;auditLoading=true;try{dataAudit=await loadDataAudit();if(withRows||route()==='audit'){const r=await fetch(await dataUrl('./data/audit/rows.json'),{cache:'no-store'});if(!r.ok)throw Error('No se pudo cargar el detalle de auditoría.');auditRows=await r.json();}records=records.map(r=>({...r,dataQuality:qualityForRol(dataAudit,r.rol)}));auditError='';}catch(e){auditError=e.message;toast(e.message,true);}finally{auditLoading=false;render();}}
function auditView(){if((!dataAudit||!auditRows)&&!auditLoading&&!auditError)ensureDataAudit(true);if(!dataAudit||!auditRows)return heading('Auditoría de datos','Contraste de planilla, catastro y precarga.')+`<p>${h(auditError||'Cargando resultados…')}</p>`;const s=dataAudit.summary;return heading('Auditoría de datos','Planilla actualizada al '+date(s.asOf)+' · Catastro y PRC: copia del '+date(s.cartographyAsOf),`<a class="btn btn-primary" href="./data/audit/Auditoria_Predios_DOM_2026-11-05.csv" download>Descargar auditoría CSV</a>`)+`<div class="stats">${[['ROL contrastados',s.rolesReviewed],['Actos revisados',s.actsReviewed],['ROL con direcciones por revisar',s.rolesWithAddressConflict],['Actos con hallazgos en fuente',s.sourceActsWithFindings]].map(([label,value])=>`<div class="stat"><span>${label}</span><strong>${value.toLocaleString('es-CL')}</strong></div>`).join('')}</div>`+panel('Alcance y resultado',`<div class="panel-body"><p>${s.cellComparisons.toLocaleString('es-CL')} comparaciones de atributos con celdas de origen. Diferencias de importación no resueltas: <b>${s.importMismatches}</b>. Las observaciones de fuente se conservan para revisión; una discrepancia no prueba que el antecedente sea erróneo.</p><p>La versión actual contiene ${s.source.eventsByKind.DECLARACION_JURADA} declaraciones juradas. ${s.source.unlinkedEventCount} actos carecen de ROL vinculable inequívocamente. ${s.removedRoleCount} ROL de la copia anterior ya no tienen enlace inequívoco en la planilla actual: <a href="./data/audit/removed-roles.json" download>descargar detalle</a>.</p><p>Se contrastaron EDIFICACIÓN, OBRA MENOR, D. JURADA y 1988. Hoja excluida del importador: ${s.excludedSheets.map(h).join(', ')}. Hay ${s.cartographicIntegrityFindings} contornos cuya área se redondea a cero y requieren revisión de origen. <a href="./data/audit/integrity-findings.json" download>Ver detalle geométrico</a>. Los documentos firmados, las fichas validadas de usuarios y la vigencia normativa requieren cotejo profesional; no se sobrescriben automáticamente.</p><a href="${h(s.source.url)}" target="_blank" rel="noopener">Abrir planilla de origen</a></div>`)+panel('Resultados por ROL',`<div class="panel-body"><div class="form-grid">${input('auditSearch','Buscar ROL o dirección',auditSearch)}<div class="field"><label for="auditFilter">Filtrar hallazgo</label><select id="auditFilter"><option value="">Todos los ROL</option><option value="ADDRESS_REVIEW" ${auditFilter==='ADDRESS_REVIEW'?'selected':''}>Direcciones que requieren revisión</option>${Object.entries(AUDIT_LABELS).map(([code,label])=>`<option value="${code}" ${auditFilter===code?'selected':''}>${h(label)} (${s.codes[code]||0})</option>`).join('')}</select></div></div></div><div id="auditResults">${auditResults()}</div>`);}
function auditResults(){if(!auditRows)return '';const q=auditSearch.toLocaleUpperCase(),rows=auditRows.filter(r=>(!q||[r.rol,...r.documentaryAddresses,...r.cadastralAddresses].join(' ').toLocaleUpperCase().includes(q))&&(!auditFilter||(auditFilter==='ADDRESS_REVIEW'?r.requiresAddressReview:r.codes.includes(auditFilter)))),page=rows.slice(auditPage*30,auditPage*30+30);return `<p class="pagination-note">${rows.length.toLocaleString('es-CL')} ROL · Página ${auditPage+1} de ${Math.max(1,Math.ceil(rows.length/30))}</p><div class="table-wrap"><table><thead><tr><th>ROL</th><th>Dirección planilla DOM</th><th>Dirección catastro</th><th>Revisión y referencias</th></tr></thead><tbody>${page.map(r=>`<tr><td><a class="record-title" href="#predio/${h(r.rol)}">${h(r.rol)}</a><small>${r.historyCount} actos · ${r.contours} contornos</small></td><td>${r.documentaryAddresses.map(h).join('<br>')||'Sin antecedente'}</td><td>${r.cadastralAddresses.map(h).join('<br>')||'Sin contorno'}</td><td>${r.codes.map(c=>h(AUDIT_LABELS[c]||c)).join('<br>')||'Sin discrepancias detectadas por estas reglas'}<small>${r.sourceReferences.map(h).join(' · ')}</small></td></tr>`).join('')}</tbody></table></div><div class="button-row">${auditPage?btn('Anterior','auditPage','btn-sm',`data-page="${auditPage-1}"`):''}${(auditPage+1)*30<rows.length?btn('Siguiente','auditPage','btn-sm',`data-page="${auditPage+1}"`):''}</div>`;}

async function refreshSync(){try{syncInfo=await syncStatus();syncError='';}catch(e){syncError=e.message;}}
function syncDate(value){if(!value)return 'No registrada';const d=new Date(value);return Number.isNaN(d.getTime())?h(value):new Intl.DateTimeFormat('es-CL',{timeZone:'America/Santiago',dateStyle:'medium',timeStyle:'short'}).format(d);}
function syncView(){const state=freshness(syncInfo),s=syncInfo||{},next=nextRun(s.schedule);return heading('Fuentes y actualización','Información DOM, trazabilidad de las importaciones y control de vigencia.')+panel('Estado de sincronización',`<div class="panel-body"><p class="sync-state ${state.tone}" role="status">${h(syncError||state.label)}</p><div class="sync-facts">${fact('Última carga verificada',syncDate(s.lastSuccessAt))}${fact('Última revisión',syncDate(s.lastAttempt?.at||s.checkedAt))}${fact('Próxima revisión',next?syncDate(next):'Programación no confirmada')}${fact('Frecuencia',s.schedule?.enabled?'Cada 2 días · 06:00 · Chile':'Sin programación confirmada')}</div>${s.lastAttempt?.ok===false?`<p class="warning">${h(s.lastAttempt.error)}. Se mantiene la última versión correcta.</p>`:''}<p>La fecha de revisión indica cuándo se consultó la fuente. La modificación de origen indica cuándo cambió el archivo. La importación técnica no reemplaza la validación profesional.</p></div>`)+panel('Fuentes registradas',`<div class="table-wrap sync-sources"><table><thead><tr><th>Fuente</th><th>Estado y alcance</th><th>Modificación de origen</th><th>Última revisión</th></tr></thead><tbody>${(s.sources||[]).map(v=>`<tr><td>${h(v.name)}${/^https:\/\/(drive|docs)\.google\.com\//.test(v.url||'')?`<small><a href="${h(v.url)}" target="_blank" rel="noopener">Abrir fuente</a></small>`:''}</td><td><b>${h(({IMPORTED:'Incorporada',UNCHANGED:'Revisada sin cambios',MONITORED:'Monitoreada',SNAPSHOT:'Versión aportada',REVIEW:'Requiere revisión',UNAVAILABLE:'Acceso pendiente',ERROR:'Error'})[v.state]||v.state)}</b><small>${h(v.details||'')}${v.rows!=null?' · '+Number(v.rows).toLocaleString('es-CL')+' registros':''}</small></td><td>${syncDate(v.modifiedAt)}</td><td>${syncDate(v.checkedAt)}</td></tr>`).join('')||'<tr><td colspan="4">El estado remoto aún no está disponible.</td></tr>'}</tbody></table></div>`)+panel('Reglas de actualización',`<div class="panel-body"><p>Las fuentes se consultan en lectura. No se modifican las planillas originales ni se crean correlativos o pagos a partir de sus textos.</p><p>Las fichas validadas por la DOM y los certificados emitidos se conservan. Una diferencia entre fuentes requiere cotejo; una nueva importación no convierte un antecedente en validado.</p><p>Los registros sin ROL inequívoco se mantienen separados. Los cambios en formatos de Borradores, cartografía o normativa generan revisión antes de reemplazar una versión validada.</p><a class="btn btn-sm" href="./data/external/unlinked.json" download>Descargar registros complementarios sin ROL vinculable</a></div>`);}
function externalPanel(rol){if(!externalData.has(rol)&&!externalPending.has(rol)){externalPending.add(rol);externalForRol(rol).then(v=>externalData.set(rol,v)).catch(e=>externalData.set(rol,{error:e.message})).finally(()=>{if(route()==='predio/'+rol)render();});}const data=externalData.get(rol);return panel('Certificados y expedientes en planillas',`<div class="panel-body"><p>Antecedentes documentales sincronizados. No equivalen a solicitudes operativas ni acreditan pago, firma o aprobación del sistema.</p>${data?.error?`<p class="warning">${h(data.error)}</p>`:Array.isArray(data)?data.length?`<details><summary>${data.length} registros vinculados al ROL · Ver antecedentes</summary><div class="table-wrap"><table><thead><tr><th>Fuente</th><th>Referencia</th><th>Fecha</th><th>Dirección / estado documental</th></tr></thead><tbody>${data.map(v=>`<tr><td>${h(v.source==='certificates'?'Certificados':'Expedientes')} · ${h(v.sheet)}<small>Fila ${v.row}</small></td><td>${h(v.fields.type||v.sheet)}<small>${h(v.fields.number||v.fields.entry||v.fields.folio||'Sin referencia')}${v.fields.numberAmbiguous?' · Número requiere cotejo':''}</small></td><td>${h(v.fields.date||'Sin fecha')}</td><td>${h(v.fields.address||'')}<small>${h(v.fields.status||v.fields.approvalReference||'')}${v.issues.length?' · '+v.issues.map(h).join(' · '):''}</small></td></tr>`).join('')}</tbody></table></div></details>`:'<p>No hay registros vinculables en estas fuentes.</p>':'<p>Consultando planillas sincronizadas…</p>'}</div>`);}
setInterval(async()=>{await refreshSync();const el=document.querySelector('#syncIndicator');if(el)el.textContent=syncError?'Actualización no disponible':freshness(syncInfo).label;},300000);

function cloudPager(){if(!store.isCloud())return '';return `<div class="button-row pagination-note"><span>Página ${cloudPage+1} · ${cloudLoading?'Consultando…':filtered().length+' registros cargados'}</span>${cloudPage?btn('Anterior','cloudPage','btn-sm',`data-page="${cloudPage-1}" ${cloudLoading?'disabled':''}`):''}${cloudPageInfo.hasMore?btn('Siguiente','cloudPage','btn-sm',`data-page="${cloudPage+1}" ${cloudLoading?'disabled':''}`):''}${btn('Actualizar','cloudRefresh','btn-sm',cloudLoading?'disabled':'')}</div>${cloudSummary?`<p class="pagination-note">Indicadores generales consultados: ${h(syncDate(cloudSummary.at))}.</p>`:''}`;}
function syncCloudView(){
 if(!store.isCloud()||!store.currentUser())return;
 const page=route().split('/')[0],id=route().split('/')[1];
 if(['dashboard','requests'].includes(page)&&(!cloudSummary||Date.now()-Date.parse(cloudSummary.at)>store.readPolicy.summaryCacheMs)&&!summaryBusy){summaryBusy=true;store.readSummary().then(s=>{cloudSummary=s;render()}).catch(e=>toast('Indicadores no disponibles: '+e.message,true)).finally(()=>summaryBusy=false);}
 if(page==='notifications'&&!noticeLoaded&&!noticeLoading)loadNoticeHistory();
 const isDocument=['detail','preview'].includes(page),isList=['dashboard','requests','predio'].includes(page);
 const f=['requests','dashboard'].includes(page)?{...filter,q:cloudSearchTerm,searchField:cloudSearchField,tab}:page==='predio'?{q:id,searchField:'rol'}:{};
 const key=isDocument?'document:'+id:isList?page+':'+JSON.stringify(f)+':'+cloudPage:'idle';
 if(key===cloudContext)return;cloudContext=key;cloudError='';store.watchRequest(null);
 if(isDocument){cloudDetailLoading=true;cloudMissingId='';store.watchRequest(id,()=>{if(cloudContext!==key)return;cloudDetailLoading=false;cloudMissingId=id;records=records.filter(r=>r.id!==id);render();},e=>{if(cloudContext!==key)return;cloudDetailLoading=false;cloudError=e.message;toast(e.message,true);render();});return;}
 cloudDetailLoading=false;if(!isList){cloudLoading=false;return;}
 cloudLoading=true;const cursor=page==='requests'?cloudCursors[cloudPage]:null;
 store.readRequestPage(f,cursor).then(result=>{if(cloudContext!==key)return;cloudPageInfo=result;if(page==='requests')cloudCursors[cloudPage+1]=result.cursor;cloudLoading=false;store.acceptRows(result.rows);}).catch(e=>{if(cloudContext!==key)return;cloudLoading=false;cloudError=e.message;render();});
}
function allNotices(){return [...new Map([...noticeHistory,...notifications].map(n=>[n.id,n])).values()].sort((a,b)=>b.createdAt.localeCompare(a.createdAt));}
async function loadNoticeHistory(){if(noticeLoading)return;noticeLoading=true;try{const page=await store.notificationPage(noticeCursor);noticeHistory=[...noticeHistory,...page.rows];noticeCursor=page.cursor;noticeHasMore=page.hasMore;noticeLoaded=true;}catch(e){noticeLoaded=true;toast('No se pudo consultar el historial: '+e.message,true);}finally{noticeLoading=false;if(route()==='notifications')render();}}
document.addEventListener('keydown',e=>{if(e.target.id==='searchRecords'&&e.key==='Enter'&&store.isCloud()){cloudSearchTerm=filter.q.trim();cloudPage=0;cloudCursors=[null];cloudContext='';render();}});
window.addEventListener('pagehide',()=>{clearTimeout(hiddenTimer);directorySubscription?.();notificationSubscription?.();notificationSubscription=null;store.closeReads();});
window.addEventListener('pageshow',e=>{if(e.persisted)location.reload();});
document.addEventListener('visibilitychange',()=>{clearTimeout(hiddenTimer);if(document.hidden){hiddenTimer=setTimeout(()=>{store.pauseLiveReads();notificationSubscription=null;cloudContext='';},store.readPolicy.hiddenGraceMs);}else if(store.currentUser()){subscribeTeam();syncCloudView();}});

window.addEventListener('resize',()=>{const banner=document.querySelector('.demo-banner');if(banner)document.documentElement.style.setProperty('--demo-banner-height',banner.offsetHeight+'px');});
